include!("/home/tobias/Projects/bennett-workspace/bennett-isa-spec-council-80732c7/reference-interpreter/tests/isa09_adjoint_table.rs");
fn main() {
    for (tag, body) in [
        ("unmatched_alloc", "qloop 0 {\nd = qalloc any 1\n}"),
        ("unmatched_predicate", "qloop 0 {\nqpred x\n}"),
        ("balanced", "qloop 0 {\nd = qalloc any 1\nqfree d\n}"),
    ] {
        let sig = r#"{"abi":"0.9","args":[],"bounds":[0],"in":[],"kind":"perm_action","mem":[],"mut":[1],"tier":"q"}"#;
        let src = support::object(&[("a",sig,&format!("perm_action @a (x:wire mut) () () () ()\nregs {{  }} bounds {{0}}\n^entry():\n{body}"))],"{}", "").replace("0.8","0.9");
        let base = support::rehash(&src);
        let (text,root)=attach(&base,vec![support::json(CLAIM)]);
        let o=Object::parse(&text).unwrap();
        o.check_hashes().unwrap();
        println!("{tag}: claim={:?}; certificate={:?}", o.verify_claim(&root,0),o.verify_certificate().map(|c|c.claims[0].verdict.clone()));
    }
}
